package detsample

import "testing"

// Cross-language conformance for the sequence layer: the Go VerifySequence /
// MAEDistance must reproduce the same aggregation and distance the Python
// reference committed to testdata/conformance_vectors.json (generated by
// scripts/gen_conformance_vectors.py). This extends the primitive-level parity
// (RNG/pipeline/seed) to the sequence level.

type confSeqPosition struct {
	Logprobs      map[string]string `json:"logprobs"` // JSON null -> nil (missing data)
	ReportedToken string            `json:"reported_token"`
}

type confSeqExpected struct {
	Verdict       string `json:"verdict"`
	FraudPosition int    `json:"fraud_position"`
	NHonest       int    `json:"n_honest"`
	NInconclusive int    `json:"n_inconclusive"`
}

type confSequenceCase struct {
	Name            string            `json:"name"`
	BaseSeed        string            `json:"base_seed"`
	ContractVersion string            `json:"contract_version"`
	SeedDomain      string            `json:"seed_domain"`
	Temperature     string            `json:"temperature"`
	TopP            *string           `json:"top_p"`
	TopK            *int              `json:"top_k"`
	MinP            *string           `json:"min_p"`
	Greedy          bool              `json:"greedy"`
	Positions       []confSeqPosition `json:"positions"`
	Expected        confSeqExpected   `json:"expected"`
}

type confDistanceCase struct {
	Name        string               `json:"name"`
	Executor    []map[string]float64 `json:"executor"`
	Validator   []map[string]float64 `json:"validator"`
	ExpectedMAE float64              `json:"expected_mae"`
}

func TestSequenceConformance(t *testing.T) {
	var v struct {
		Cases []confSequenceCase `json:"sequence_cases"`
	}
	decodeVectors(t, &v)
	if len(v.Cases) == 0 {
		t.Fatal("no sequence_cases in vectors")
	}
	for _, c := range v.Cases {
		c := c
		t.Run(c.Name, func(t *testing.T) {
			positions := make([]SequencePosition, len(c.Positions))
			for i, p := range c.Positions {
				positions[i] = SequencePosition{
					Logprobs:      p.Logprobs,
					ReportedToken: p.ReportedToken,
				}
			}
			r := VerifySequence(SequenceRequest{
				ContractVersion: c.ContractVersion,
				SeedDomain:      c.SeedDomain,
				BaseSeed:        c.BaseSeed,
				Temperature:     c.Temperature,
				TopP:            c.TopP,
				TopK:            c.TopK,
				MinP:            c.MinP,
				Greedy:          c.Greedy,
			}, positions)

			if string(r.Verdict) != c.Expected.Verdict {
				t.Errorf("verdict = %s (%s), want %s", r.Verdict, r.Reason, c.Expected.Verdict)
			}
			if r.FraudPosition != c.Expected.FraudPosition {
				t.Errorf("fraudPosition = %d, want %d", r.FraudPosition, c.Expected.FraudPosition)
			}
			if r.NHonest != c.Expected.NHonest {
				t.Errorf("nHonest = %d, want %d", r.NHonest, c.Expected.NHonest)
			}
			if r.NInconclusive != c.Expected.NInconclusive {
				t.Errorf("nInconclusive = %d, want %d", r.NInconclusive, c.Expected.NInconclusive)
			}
		})
	}
}

func TestDistanceConformance(t *testing.T) {
	var v struct {
		Cases []confDistanceCase `json:"distance_cases"`
	}
	decodeVectors(t, &v)
	if len(v.Cases) == 0 {
		t.Fatal("no distance_cases in vectors")
	}
	for _, c := range v.Cases {
		c := c
		t.Run(c.Name, func(t *testing.T) {
			// Exact equality: sorted-key summation makes the float64 accumulation
			// order identical to the Python reference (byte-exact distance).
			if got := MAEDistance(c.Executor, c.Validator); got != c.ExpectedMAE {
				t.Errorf("MAEDistance = %v, want %v", got, c.ExpectedMAE)
			}
		})
	}
}
